  function tint(c, color, alpha) { const o = cnv(c.width, c.height), g = o.getContext('2d'); g.drawImage(c, 0, 0); g.globalCompositeOperation = 'source-atop'; g.globalAlpha = alpha; g.fillStyle = color; g.fillRect(0, 0, c.width, c.height); return o; }

  // ------------------------------------------------------------------ PALETTE
  const P = {
    skin: ['#f6cfae', '#dfa585'], skinTan: ['#d9a07a', '#b57c58'], skinDeep: ['#a8704a', '#84553a'],
    hBrown: ['#7a4526', '#55301a', '#a0643a'], hBlonde: ['#f0d27a', '#c9a24a', '#fff2b8'], hGrey: ['#c4c0bc', '#8e8a86', '#e8e4e0'],
    hBlack: ['#3a2a2a', '#221818', '#5a4444'], hRed: ['#b8542a', '#86391c', '#de7a44'], hDark: ['#4a2e1e', '#30180e', '#6a4430'],
    cloak: ['#2c3a78', '#1c2654', '#4558a8'], gold: ['#e8b84a', '#a87a24', '#fff0a0'],
  };

  // =================================================================== CHARACTERS
  // 20 x 30 body box (drawn into a 22 x 36 canvas so hats & outlines fit). Light comes from the upper left.
  function drawHuman(p, dir, f, L) {
    const ox = 1, oy = 5;
    const bob = (f === 1 || f === 3) ? -1 : 0;
    const R = (x, y, w, h, c) => p.r(ox + x, oy + y, w, h, c);
    const RB = (x, y, w, h, c) => p.r(ox + x, oy + y + bob, w, h, c);
    const PB = (x, y, c) => p.p(ox + x, oy + y + bob, c);
    const E = (cx, cy, rx, ry, c) => p.e(ox + cx, oy + cy + bob, rx, ry, c);
    const POLY = (pts, c) => p.poly(pts.map(([x, y]) => [ox + x, oy + y + bob]), c);
    const [sk, skS] = L.skin || P.skin; const skL = lt(sk, 0.2);
    const [hb, hs, hl] = L.hair || P.hBrown; const hd = dk(hs, 0.3);
    const [tb, ts, tl] = L.top || ['#6a7a3a', '#4a5a2a', '#8a9a5a']; const td = dk(ts, 0.3);
    const trim = L.trim || null, trimD = trim ? dk(trim, 0.35) : null;
    const [ub, us] = L.under || ['#3a2a2a', '#2a1c1c'];
    const [lb, ls] = L.legs || ['#5a4a3a', '#3e3226'];
    const boots = L.boots || '#4a2e1a', bootsL = lt(boots, 0.2), bootsD = dk(boots, 0.35);
    const eye = L.eye || '#5a3a1e';
    const outfit = L.outfit || 'tunic';
    const side = dir === 'left';
    const longSkirt = outfit === 'cloak' || outfit === 'dress' || outfit === 'robe';
    const swing = f === 1 ? 1 : f === 3 ? -1 : 0;

    // ---------------------------------------------------------------- legs & boots
    const boot = (x, y, w, facingLeft) => { R(x, y, w, 3, boots); R(x, y, w, 1, bootsL); R(x, y + 2, w, 1, bootsD); if (facingLeft) R(x - 1, y + 1, 1, 2, boots); };
    if (!side) {
      const lUp = f === 1 ? 1 : 0, rUp = f === 3 ? 1 : 0;
      if (!longSkirt) {
        R(6, 22, 3, 5 - lUp, lb); R(6, 22, 1, 5 - lUp, lt(lb, 0.15)); R(8, 22, 1, 5 - lUp, ls);
        R(11, 22, 3, 5 - rUp, lb); R(13, 22, 1, 5 - rUp, ls);
      }
      boot(5, 27 - lUp, 4); boot(11, 27 - rUp, 4);
    } else {
      const legs = f === 1 ? [[4, 11]] : f === 3 ? [[6, 10]] : [[8, 8]];
      const [a, b2] = legs[0];
      if (!longSkirt) { R(b2, 22, 3, 5, ls); R(a, 22, 3, 5, lb); R(a, 22, 1, 5, lt(lb, 0.15)); }
      if (a !== b2) boot(b2, 27, 4); boot(a, 27, 4, true);
    }

    // ---------------------------------------------------------------- body
    if (outfit === 'cloak') {
      for (let y = 14 + bob; y <= 28; y++) {
        let x0, x1;
        if (side) { x0 = 5 - Math.floor((y - 14) / 4); x1 = 13 + Math.floor((y - 14) / 4); }
        else { const hw = Math.min(9, 6 + Math.floor((y - 14) / 3)); x0 = 10 - hw; x1 = 9 + hw; }
        R(x0, y, x1 - x0 + 1, 1, tb); R(x0, y, 2, 1, side ? tb : tl); R(x1 - 1, y, 2, 1, ts);
        if (y > 18) { // soft folds
          const fa = side ? 8 : 6, fb = side ? 11 : 13;
          R(fa, y, 1, 1, ts); R(fa + 1, y, 1, 1, tl); R(fb, y, 1, 1, ts); if (!side && y > 22) R(3, y, 1, 1, ts);
        }
        if (y === 28) R(x0, y, x1 - x0 + 1, 1, td);
      }
      if (dir === 'down') {
        for (let y = 17 + bob; y <= 28; y++) { R(8, y, 4, 1, ub); R(8, y, 1, 1, lt(ub, 0.15)); }
        if (trim) {
          for (let y = 16 + bob; y <= 28; y++) { R(7, y, 1, 1, y % 2 ? trim : trimD); R(12, y, 1, 1, y % 2 ? trim : trimD); }
          R(1, 28, 18, 1, trim); for (let x = 2; x < 18; x += 3) { R(x, 27, 1, 1, trim); R(x + 1, 28, 1, 1, trimD); }
        }
        E(9.5, 14.5, 6.5, 2, ts); RB(4, 13, 12, 1, tb); RB(5, 13, 3, 1, tl);
        RB(9, 15, 2, 2, P.gold[0]); PB(9, 15, P.gold[2]); PB(10, 16, P.gold[1]);
        R(3, 21, 1, 2, sk);
      } else if (dir === 'up') {
        E(9.5, 15, 6.5, 2.6, ts); RB(5, 13, 10, 1, tl); RB(4, 15, 12, 1, td);
        for (let y = 18; y <= 27; y++) { R(9, y, 2, 1, ts); }
        if (trim) { R(1, 28, 18, 1, trim); for (let x = 2; x < 18; x += 3) R(x, 27, 1, 1, trim); }
      } else {
        E(9, 14.5, 5, 2, ts); RB(5, 13, 8, 1, tb);
        if (trim) { for (let y = 16 + bob; y <= 28; y++) R(5 - Math.floor((y - 14) / 4), y, 1, 1, y % 2 ? trim : trimD); R(2, 28, 13, 1, trim); }
      }
    } else if (outfit === 'dress') {
      const sb = L.sleeve || '#efe4cc', ss = dk(sb, 0.18), sl = '#fffaf0';
      if (!side) {
        for (let y = 21; y <= 28; y++) { const k = Math.floor((y - 21) / 2); const x0 = 5 - k, x1 = 14 + k; R(x0, y, x1 - x0 + 1, 1, tb); R(x0, y, 1, 1, tl); R(x1, y, 1, 1, ts); if (y > 22) { R(7, y, 1, 1, ts); R(12, y, 1, 1, ts); } }
        R(2, 28, 16, 1, td);
        RB(6, 15, 8, 7, tb); RB(6, 15, 1, 7, tl); RB(13, 15, 1, 7, ts);
        RB(7, 14, 6, 2, sb); RB(8, 14, 4, 1, sl);
        if (dir === 'down') { for (let y = 16; y < 21; y++) { PB(9, y, y % 2 ? sb : ts); PB(10, y, y % 2 ? ts : sb); } if (L.pendant) { PB(9, 15, L.pendant); PB(10, 15, L.pendant); } }
        E(4, 16, 2.6, 2.6, sb); E(15, 16, 2.6, 2.6, sb); PB(3, 15, sl); PB(16, 17, ss);
        RB(3, 18, 2, 3, sb); RB(15, 18, 2, 3, ss); RB(3, 21, 2, 1, sk); RB(15, 21, 2, 1, skS);
      } else {
        for (let y = 21; y <= 28; y++) { const k = Math.floor((y - 21) / 2); R(6 - k, y, 9 + 2 * k, 1, tb); R(6 - k, y, 1, 1, tl); R(14 + k, y, 1, 1, ts); }
        R(3, 28, 14, 1, td);
        RB(6, 15, 8, 7, tb); RB(13, 15, 1, 7, ts); RB(7, 14, 6, 2, sb);
        E(9 + swing, 17, 2.6, 2.6, sb); RB(8 + swing, 19, 3, 2, sb); RB(8 + swing, 21, 2, 1, sk);
      }
    } else if (outfit === 'robe') {
      for (let y = 14 + bob; y <= 28; y++) {
        const k = Math.floor((y - 14) / 4); const x0 = side ? 5 - k : 4 - k, x1 = side ? 14 + k : 15 + k;
        R(x0, y, x1 - x0 + 1, 1, tb); R(x0, y, 1, 1, tl); R(x1 - 1, y, 2, 1, ts);
        if (y > 20) { R(side ? 9 : 7, y, 1, 1, ts); if (!side) R(12, y, 1, 1, ts); }
      }
      R(side ? 2 : 1, 28, side ? 15 : 18, 1, td);
      if (trim) { R(side ? 2 : 1, 27, side ? 15 : 18, 1, trim); if (dir === 'down') for (let y = 15 + bob; y < 27; y++) R(9, y, 2, 1, y % 3 ? trim : trimD); }
      RB(side ? 5 : 4, 20, side ? 10 : 12, 2, L.belt || '#5a3a1a'); if (dir === 'down') RB(9, 20, 2, 2, P.gold[0]);
      if (!side) { RB(1, 15, 3, 7, ts); RB(16, 15, 3, 7, td); RB(1, 15, 1, 6, tb); RB(2, 22, 2, 1, sk); RB(16, 22, 2, 1, skS); }
      else { RB(8 + swing, 15, 4, 7, ts); RB(8 + swing, 15, 1, 7, tb); RB(9 + swing, 22, 2, 1, sk); }
    } else { // tunic
      if (!side) {
        RB(5, 14, 10, 9, tb); RB(5, 14, 2, 9, tl); RB(13, 14, 2, 9, ts);
        R(4, 22 + bob, 12, 2, ts); R(4, 22 + bob, 2, 1, tb);
        RB(5, 20, 10, 2, L.belt || '#4a2e1a'); if (dir === 'down') { RB(9, 20, 2, 2, P.gold[0]); PB(9, 20, P.gold[2]); }
        if (dir === 'down') { RB(7, 14, 6, 1, L.collar || ts); PB(9, 15, ts); PB(10, 15, ts); }
        const la = Math.max(0, swing), ra = Math.max(0, -swing);
        RB(3, 15 + la, 2, 6, ts); RB(3, 15 + la, 1, 6, tb); RB(15, 15 + ra, 2, 6, td);
        RB(3, 21 + la, 2, 1, sk); RB(15, 21 + ra, 2, 1, skS);
      } else {
        RB(6, 14, 8, 9, tb); RB(12, 14, 2, 9, ts); R(5, 22 + bob, 10, 2, ts);
        RB(6, 20, 8, 2, L.belt || '#4a2e1a');
        RB(8 + swing, 15, 3, 6, ts); RB(8 + swing, 15, 1, 6, tb); RB(8 + swing, 21, 3, 1, sk);
      }
    }
    if (L.apron && dir !== 'up') {
      if (!side) { RB(6, 17, 8, 10, '#f4f0e6'); RB(6, 17, 8, 1, '#d8d2c4'); RB(13, 18, 1, 9, '#d8d2c4'); RB(8, 22, 4, 2, '#e4ded2'); }
      else RB(5, 17, 3, 10, '#f4f0e6');
    }

    // ---------------------------------------------------------------- head
    const hs2 = L.hairStyle || 'short';
    const bald = hs2 === 'bald';
    const longHair = hs2 === 'wavy' || hs2 === 'long';
    if (dir === 'down') {
      if (longHair) { RB(2, 7, 4, 14, hb); RB(14, 7, 4, 14, hb); RB(2, 8, 1, 12, hl); RB(17, 8, 1, 12, hs); for (let y = 10; y < 21; y += 3) { PB(3, y, hs); PB(16, y + 1, hl); } PB(2, 21, hs); PB(17, 20, hs); }
      E(9.5, 7, 7, 7, bald ? sk : hb);
      if (bald) { E(8, 4, 3, 2, skL); PB(7, 3, '#fff6ea'); }
      RB(5, 6, 10, 7, sk); RB(6, 13, 8, 1, sk); RB(14, 6, 1, 7, skS); RB(7, 13, 6, 1, skS); RB(5, 6, 10, 1, skS);
      // eyes
      for (const ex of [6, 12]) { RB(ex, 8, 2, 1, '#2a1a14'); PB(ex, 9, eye); PB(ex + 1, 9, '#ffffff'); RB(ex, 10, 2, 1, dk(eye, 0.3)); }
      PB(10, 11, skS); RB(9, 12, 2, 1, '#c0645a');
      PB(5, 11, '#f2a090'); PB(14, 11, '#f2a090');
      if (!bald) {
        RB(3, 2, 14, 4, hb); RB(3, 6, 3, 1, hb); RB(12, 6, 5, 1, hb); PB(11, 6, hb);
        RB(5, 1, 4, 1, hl); RB(6, 2, 3, 1, hl); RB(12, 2, 2, 1, hl); PB(4, 4, hs); PB(8, 4, hs); PB(8, 5, hs); PB(14, 5, hs); PB(15, 4, hs);
        const sideLen = hs2 === 'short' ? 4 : 7;
        RB(3, 6, 2, sideLen, hb); RB(15, 6, 2, sideLen, hb); RB(16, 7, 1, sideLen - 1, hs); RB(3, 7, 1, sideLen - 1, hl);
        if (hs2 === 'short') { PB(4, 9, sk); PB(15, 9, sk); PB(4, 10, skS); PB(15, 10, skS); }
      } else { RB(3, 7, 2, 4, L.beard || hs); RB(15, 7, 2, 4, L.beard || hs); }
      if (hs2 === 'braid') { for (let y = 12; y <= 22; y++) { RB(15, y, 3, 1, y % 2 ? hb : hs); PB(15 + (y % 2), y, hl); } RB(15, 23, 3, 1, L.tie || '#c03a3a'); PB(16, 24, hs); }
      if (L.flower) { E(15, 3, 1.8, 1.8, L.flower); PB(15, 3, '#ffffff'); PB(14, 2, lt(L.flower, 0.4)); }
      if (hs2 === 'bun') { E(9.5, 0, 3, 2.2, hb); RB(8, -1, 2, 1, hl); }
      if (L.beard) { RB(5, 11, 10, 4, L.beard); RB(6, 15, 8, 1, L.beard); RB(7, 16, 6, 1, dk(L.beard, 0.15)); RB(9, 12, 2, 1, '#7a3a30'); RB(5, 11, 1, 3, lt(L.beard, 0.2)); RB(4, 8, 1, 4, L.beard); RB(15, 8, 1, 4, L.beard); }
      if (L.moustache) { RB(7, 11, 6, 1, L.moustache); PB(6, 12, L.moustache); PB(13, 12, L.moustache); }
    } else if (dir === 'up') {
      if (longHair) { RB(3, 8, 14, 13, hb); RB(4, 19, 12, 2, hs); RB(3, 9, 1, 10, hl); RB(16, 9, 1, 10, hs); PB(7, 14, hl); PB(7, 15, hl); PB(12, 16, hs); PB(12, 17, hs); }
      E(9.5, 7, 7, 7, bald ? sk : hb);
      if (!bald) { RB(5, 1, 5, 1, hl); RB(6, 2, 3, 1, hl); RB(4, 3, 1, 2, hl); RB(4, 11, 12, 2, hs); PB(7, 6, hs); PB(8, 7, hs); PB(12, 5, hs); PB(11, 8, hs); PB(13, 3, hl); }
      else { RB(4, 8, 12, 4, L.beard || hs); E(8, 4, 3, 2, skL); }
      if (hs2 === 'braid') { for (let y = 12; y <= 23; y++) { RB(9, y, 2, 1, y % 2 ? hb : hs); PB(9 + (y % 2), y, hl); } RB(9, 24, 2, 1, L.tie || '#c03a3a'); }
      if (hs2 === 'bun') { E(9.5, 2, 3, 2.4, hs); }
      if (L.flower) E(15, 3, 1.8, 1.8, L.flower);
    } else { // left
      if (longHair) { RB(10, 7, 7, 14, hb); RB(16, 8, 1, 12, hs); for (let y = 10; y < 20; y += 3) PB(13, y, hl); }
      E(10.5, 7, 6.5, 7, bald ? sk : hb);
      if (bald) { E(9, 4, 3, 2, skL); }
      RB(3, 6, 7, 7, sk); RB(4, 13, 5, 1, sk); PB(2, 10, sk); PB(2, 11, skS); RB(3, 6, 7, 1, skS);
      RB(4, 8, 2, 1, '#2a1a14'); PB(4, 9, eye); PB(5, 9, '#ffffff'); RB(4, 10, 2, 1, dk(eye, 0.3));
      PB(3, 12, '#c0645a'); PB(6, 11, '#f2a090');
      RB(10, 8, 2, 3, sk); PB(10, 9, skS);
      if (!bald) {
        RB(3, 2, 10, 4, hb); RB(3, 6, 2, 1, hb); RB(5, 1, 5, 1, hl); RB(6, 2, 3, 1, hl); PB(7, 4, hs); PB(11, 4, hs);
        if (hs2 === 'short') RB(10, 6, 3, 2, hb); else RB(12, 6, 4, 7, hb);
        RB(15, 6, 1, 7, hs);
      } else RB(11, 7, 4, 4, L.beard || hs);
      if (hs2 === 'braid') { for (let y = 12; y <= 21; y++) { RB(13, y, 2, 1, y % 2 ? hb : hs); } RB(13, 22, 2, 1, L.tie || '#c03a3a'); }
      if (hs2 === 'bun') E(12, 1, 2.6, 2, hb);
      if (L.flower) E(12, 3, 1.8, 1.8, L.flower);
      if (L.beard) { RB(3, 11, 6, 4, L.beard); RB(4, 15, 4, 1, dk(L.beard, 0.15)); PB(3, 12, '#7a3a30'); }
      if (L.moustache) RB(2, 11, 4, 1, L.moustache);
    }

    // ---------------------------------------------------------------- hats
    const hat = L.hat, hc = L.hatCol || ['#3a6a3a', '#244a24', '#5a8a5a'];
    if (hat === 'chef') { RB(3, 1, 14, 3, '#dcdce6'); RB(3, 1, 14, 1, '#f4f4fa'); E(9.5, -2, 6.5, 3.6, '#ffffff'); E(6, -2, 2.5, 2.5, '#ffffff'); E(13, -2, 2.5, 2.5, '#f0f0f6'); PB(5, -3, '#ffffff'); RB(12, -1, 3, 1, '#e4e4ec'); }
    if (hat === 'bard') {
      E(9.5, 1.6, 6.5, 3, hc[0]); RB(2, 3, 16, 2, hc[1]); RB(4, 0, 5, 1, hc[2]); RB(2, 3, 16, 1, hc[0]);
      const fx = side ? 12 : 14; for (let i = 0; i < 6; i++) PB(fx + Math.floor(i / 2), -4 + i, i % 2 ? '#e85040' : '#c02a2a'); PB(fx + 3, 2, '#f08060');
    }
    if (hat === 'cap') { RB(3, 1, 14, 4, hc[0]); RB(3, 1, 14, 1, hc[2]); RB(3, 4, 14, 1, hc[1]); RB(side ? 1 : 3, 5, side ? 6 : 14, 1, hc[1]); }
    if (hat === 'beret') { E(9.5, 2, 8, 3, hc[0]); RB(2, 3, 16, 1, hc[1]); RB(4, 0, 5, 1, hc[2]); const fx = side ? 13 : 15; RB(fx, -3, 1, 5, '#f0f0f0'); PB(fx + 1, -2, '#d8d8d8'); }
    if (hat === 'hood') { E(9.5, 7, 8, 8, hc[0]); E(8, 4, 4, 3, hc[2]); if (dir === 'down') { RB(5, 6, 10, 7, sk); for (const ex of [6, 12]) { RB(ex, 8, 2, 1, '#2a1a14'); PB(ex, 9, eye); } } if (side) { RB(3, 6, 6, 7, sk); PB(4, 9, eye); } }

    // ---------------------------------------------------------------- held items
    const it = L.item;
    function lantern(x, y) {
      const m = '#7a6040', md = '#4a3a28';
      R(x + 1, y, 2, 1, md); R(x, y + 1, 4, 1, m); R(x, y + 2, 4, 4, '#ffd860'); R(x + 1, y + 2, 2, 4, '#fffbe0');
      R(x, y + 2, 1, 4, m); R(x + 3, y + 2, 1, 4, md); R(x, y + 6, 4, 1, m); R(x + 1, y + 7, 2, 1, md);
    }
    if (it === 'lantern') {
      if (dir === 'down') { RB(16, 20, 2, 1, sk); lantern(15 + swing, 21); }
      else if (dir === 'left') { RB(3, 19, 2, 1, sk); lantern(0, 20 + (swing ? 1 : 0)); }
      else lantern(15 - swing, 19);
    }
    if (it === 'lute' && dir !== 'up') {
      if (dir === 'down') { for (let i = 0; i < 6; i++) RB(12 + Math.floor(i / 2), 18 - i, 1, 1, '#6a4024'); RB(14, 12, 2, 2, '#4a2e1a'); E(9, 20, 4, 3, '#b8783a'); E(8, 19, 2, 1.5, '#d8985a'); E(9, 20, 1.2, 1.2, '#3a2010'); }
      else { RB(2, 12, 1, 8, '#6a4024'); E(4, 20, 3, 3, '#b8783a'); E(4, 20, 1, 1, '#3a2010'); }
    }
  }

  function human(look) {
    const frames = { down: [], up: [], left: [], right: [] };
    for (const dir of ['down', 'up', 'left']) for (let f = 0; f < 4; f++) {
      const p = new Pix(22, 36); drawHuman(p, dir, f, look); p.outline(OUT);
      frames[dir].push(p.c); if (dir === 'left') frames.right.push(p.flipped());
    }
    return { frames, w: 22, h: 36, ax: 11, ay: 34 };
  }

  // =================================================================== CREATURES
  function drawDragon(p, k, col, wing, opts = {}) {
    const [b, s, l, belly] = col; const d = dk(s, 0.35), wm = mix(b, l, 0.45), wd = mix(s, b, 0.4);
    const X = v => v * k, poly = pts => pts.map(([x, y]) => [X(x), X(y)]);
    const one = v => Math.max(1, X(v));
    // far wing (behind body)
    const WINGS = [
      { pts: [[10, 9], [12.5, 1], [15, 0.2], [16, 2.6], [18, 1.5], [18.6, 3.8], [19.8, 4.6], [17, 6.8], [15.5, 9.6]], wrist: [12.5, 1], tips: [[15, 0.2], [18, 1.5], [19.8, 4.6]] },
      { pts: [[10, 9.6], [15, 4], [17.5, 3], [17.6, 5], [20.5, 5], [19, 6.6], [20, 7.8], [16.5, 8.6], [15, 10.2]], wrist: [15, 4], tips: [[17.5, 3], [20.5, 5], [20, 7.8]] },
      { pts: [[10, 10], [15, 13.5], [18.5, 15.8], [16.8, 16], [16.5, 17.2], [14.6, 16.2], [14, 16.8], [11, 12.6]], wrist: [15, 13.5], tips: [[18.5, 15.8], [16.5, 17.2], [14, 16.8]] },
    ];
    const W0 = WINGS[wing];
    p.poly(poly(W0.pts.map(([x, y]) => [x + 1.2, y - 0.6])), wd);
    // tail with spade tip
    p.poly(poly([[14, 10], [19, 12], [21.5, 9], [20.5, 13.5], [15, 14.5]]), b);
    p.poly(poly([[15, 13.5], [20.5, 13.2], [19, 14.5]]), s);
    p.poly(poly([[20.5, 8.2], [22.6, 7.4], [22, 10.5], [20.8, 10]]), l);
    // legs (far ones darker)
    p.r(X(12.5), X(14), X(2), X(2.6), d); p.r(X(7.5), X(14), X(2), X(2.6), s);
    // body
    p.e(X(11), X(11.5), X(5.4), X(3.8), b);
    p.e(X(11.5), X(13.2), X(4.6), X(2), s);                    // underside shade
    p.e(X(10.5), X(9.4), X(4), X(1.4), l);                     // back highlight
    p.e(X(10), X(13), X(3.6), X(1.8), belly);                  // belly
    for (let i = 0; i < 5; i++) p.r(X(7.4 + i * 1.3), X(12.2), one(0.4), X(1.8), mix(belly, s, 0.5)); // belly plates
    if (k >= 1.2) for (let y = 9.5; y < 12; y += 1.2) for (let x = 8 + (y * 2 % 2); x < 15; x += 1.6) p.p(X(x), X(y), mix(b, s, 0.5)); // scales
    p.r(X(7), X(16.2), X(2.6), one(0.7), s); p.r(X(12), X(16.2), X(2.6), one(0.7), d);
    p.p(X(7), X(16.6), '#f4f0e0'); p.p(X(8.2), X(16.6), '#f4f0e0'); // claws
    // neck & head
    p.poly(poly([[6, 6], [9, 7], [10, 11], [7, 11]]), b);
    p.poly(poly([[7.5, 7], [8.8, 7.5], [9.6, 10.6], [8.4, 10.6]]), belly);
    p.e(X(5), X(6), X(3.4), X(2.9), b);
    p.e(X(5.6), X(7.4), X(2.4), X(1.4), s);
    p.poly(poly([[0.2, 5.6], [3, 4.6], [3.5, 8], [0.5, 7.8]]), b);
    p.r(X(0.6), X(7.6), X(2.6), one(0.8), s);
    p.p(X(1), X(5.8), d); p.p(X(1.2), X(8.4), '#f4f0e0');      // nostril & tooth
    p.r(X(2.2), X(4.6), X(2.2), one(0.5), l);                  // brow ridge highlight
    // eye with slit pupil
    p.e(X(4.3), X(5.4), one(1.05), one(1), opts.eyeWhite || '#fff6d0');
    p.r(X(4.2), X(4.7), one(0.45), one(1.5), opts.eye || '#1c1424');
    p.p(X(3.8), X(4.9), '#ffffff');
    // horns (two-tone) & frill
    p.poly(poly([[5.5, 3.5], [6.6, 0.4], [7.2, 3.8]]), lt(l, 0.2)); p.poly(poly([[6.4, 3.6], [6.6, 0.4], [7.2, 3.8]]), mix(l, s, 0.4));
    p.poly(poly([[7, 4], [8.8, 1.8], [8.4, 5]]), lt(l, 0.2));
    p.poly(poly([[7.6, 6.6], [9.4, 5.6], [8.6, 7.8]]), s);
    for (let i = 0; i < 4; i++) p.poly(poly([[9 + i * 1.6, 8], [10 + i * 1.6, 6.4], [10.6 + i * 1.6, 8.2]]), i % 2 ? l : lt(l, 0.25));
    // near wing: membrane fanned between finger bones
    p.poly(poly(W0.pts), wm);
    const [wx, wy] = W0.wrist, [shx, shy] = W0.pts[0];
    p.ln(X(shx + 0.5), X(shy), X(wx), X(wy), s); p.ln(X(shx + 0.5), X(shy) + 1, X(wx), X(wy) + 1, s);
    W0.tips.forEach(([tx, ty], i) => { p.ln(X(wx), X(wy), X(tx), X(ty), s); if (k >= 1.5) p.ln(X(wx), X(wy) + 1, X(tx), X(ty) + 1, mix(wm, s, 0.5)); });
    p.e(X(wx), X(wy), one(0.55), one(0.55), d);
    p.poly(poly([W0.pts[W0.pts.length - 2], W0.pts[W0.pts.length - 1], [shx + 2, shy]]), mix(wm, s, 0.3));
    if (opts.cute) p.r(X(4.5), X(6.8), one(1), one(0.6), '#ff9ab8');
  }
  function dragon(col, k = 1, opts) {
    const w = Math.ceil(23.5 * k) + 2, h = Math.ceil(18 * k) + 2;
    const fr = [0, 1, 2].map(wg => { const p = new Pix(w, h); p.g.translate(1, 1); drawDragon(p, k, col, wg, opts); p.g.setTransform(1, 0, 0, 1, 0, 0); p.outline(OUT); return p; });
    return { left: fr.map(p => p.c), right: fr.map(p => p.flipped()), w, h, ax: w / 2, ay: h - 1 };
  }

  function goblinite() {
    const fr = [0, 1].map(f => {
      const p = new Pix(22, 19);
      const g = ['#617a2e', '#3f5220', '#89a446'], gd = '#2e3c16';
      // back arms/claws
      p.r(2 + f, 13, 4, 4, g[1]); p.r(16 - f, 13, 4, 4, gd);
      for (const x of [2, 4, 16, 18]) p.p(x + (x < 10 ? f : -f), 17, '#e8e0c0');
      // body
      p.e(11, 12.5, 6.5, 4.2, g[0]); p.e(12, 14, 5.5, 2.6, g[1]); p.e(9, 11, 4, 2, g[2]);
      p.e(11, 14.5, 3, 1.4, '#a8b878');                        // belly
      p.p(8, 12, gd); p.p(14, 11, gd); p.p(12, 13, gd);        // warts
      // ears with inner glow
      p.poly([[7, 6], [0, 1 + f], [5, 9]], g[0]); p.poly([[15, 6], [22, 1 + f], [17, 9]], g[1]);
      p.poly([[6.5, 6.4], [2, 3 + f], [5, 8.4]], '#c0603a'); p.poly([[15.5, 6.4], [20, 3 + f], [17, 8.4]], '#a04a2a');
      p.ln(2, 2 + f, 6, 6, g[2]);
      // head
      p.e(11, 7, 5, 4.4, g[0]); p.e(12, 9, 4, 2, g[1]); p.r(8, 3, 6, 1, g[2]); p.r(7, 4, 2, 1, g[2]);
      // glowing eyes
      p.r(7, 6, 3, 2, '#ffe040'); p.r(12, 6, 3, 2, '#ffe040'); p.p(8, 6, '#2a1400'); p.p(13, 6, '#2a1400'); p.p(7, 6, '#fffbd0'); p.p(12, 6, '#fffbd0');
      p.r(7, 5, 3, 1, gd); p.r(12, 5, 3, 1, gd);
      p.p(11, 8, gd);                                           // nose
      // mouth & fangs
      p.r(8, 9, 6, 2, '#3a0a10'); p.r(9, 10, 4, 1, '#6a1a24'); p.p(8, 9, '#ffffff'); p.p(13, 9, '#ffffff'); p.p(10, 10, '#c04050');
      // vines
      p.ln(4, 11, 18, 15, '#7a5a2a'); p.ln(5, 15, 16, 10, '#6a4a22'); p.p(10, 13, '#a07a3a'); p.p(14, 12, '#e8d8c0');
      p.outline(OUT); return p.c;
    });
    return { frames: fr, w: 22, h: 19, ax: 11, ay: 18 };
  }

  function owl() {
    return [0, 1].map(f => {
      const p = new Pix(16, 18);
      const b = '#8a6a44', bd = '#6a4e30', bl = '#a8865a';
      p.e(8, 11, 6, 6.4, b); p.e(9, 12, 5, 5, bd); p.e(8, 12.5, 4, 4.4, '#d8c098');
      for (let y = 10; y < 17; y += 2) for (let x = 6 + (y % 4 ? 1 : 0); x < 11; x += 2) p.p(x, y, '#a88a60');
      p.r(2, 9, 2, 6, bd); p.r(12, 9, 2, 6, bd); p.p(2, 10, bl);
      p.e(8, 6.5, 5.5, 4.4, b); p.e(7, 5, 3, 2, bl);
      p.e(5.6, 6.6, 2.6, 2.6, '#ece0c0'); p.e(10.4, 6.6, 2.6, 2.6, '#ece0c0');
      if (f === 0) { p.r(4, 5, 3, 3, '#ffb020'); p.r(9, 5, 3, 3, '#ffb020'); p.r(5, 6, 1, 1, '#1c1424'); p.r(10, 6, 1, 1, '#1c1424'); p.p(4, 5, '#fff0a0'); p.p(9, 5, '#fff0a0'); }
      else { p.r(4, 7, 3, 1, '#5a4024'); p.r(9, 7, 3, 1, '#5a4024'); }
      p.poly([[7, 8], [9, 8], [8, 10.5]], '#e09a30');
      p.poly([[2, 3], [3.5, 0], [5.5, 3.5]], b); p.poly([[10.5, 3.5], [12.5, 0], [14, 3]], b);
      p.r(5, 17, 2, 1, '#e09a30'); p.r(9, 17, 2, 1, '#e09a30');
      p.outline(OUT); return p.c;
    });
  }
  function bird(col = ['#5a7ab8', '#3a5a98', '#f0a040']) {
    return [0, 1].map(f => {
      const p = new Pix(11, 8);
      p.e(5.5, 4.5, 3, 2, col[0]); p.e(6, 5.4, 2, 1, lt(col[0], 0.4)); p.e(2.5, 3.5, 1.8, 1.6, col[0]); p.p(0, 3, col[2]); p.p(2, 3, '#1c1424');
      if (f === 0) p.poly([[4, 4], [7, 0], [8, 1], [6, 4]], col[1]); else p.poly([[4, 5], [8, 7], [7, 8], [5, 6]], col[1]);
      p.r(8, 4, 2, 1, col[1]);
      p.outline(OUT); return p.c;
    });
  }
  function butterfly(col) {
    return [0, 1].map(f => {
      const p = new Pix(7, 5);
      if (f === 0) { p.r(0, 0, 3, 2, col); p.r(4, 0, 3, 2, col); p.r(1, 2, 2, 2, dk(col, 0.2)); p.r(4, 2, 2, 2, dk(col, 0.2)); p.p(1, 0, lt(col, 0.5)); p.p(5, 0, lt(col, 0.5)); }
      else { p.r(1, 0, 2, 3, col); p.r(4, 0, 2, 3, col); }
      p.r(3, 0, 1, 5, '#2a1a10');
      return p.c;
    });
  }
  function possum() {
    return [0, 1].map(f => {
      const p = new Pix(18, 12);
      p.ln(12, 8, 15, 7, '#e8a0a8'); p.ln(15, 7, 16, 4 + f, '#e8a0a8'); p.p(15, 4 + f, '#e8a0a8'); p.p(16, 5 + f, '#d08890');
      p.e(9, 7.5, 5, 3.2, '#8e8a90'); p.e(10, 9, 4, 1.6, '#6e6a72'); p.e(8, 6.2, 3.6, 1.6, '#b0acb2');
      for (let i = 0; i < 5; i++) p.p(6 + i * 2, 6 + (i % 2), '#a8a4aa');
      p.e(4, 6, 3, 2.6, '#e4e0e4'); p.e(4.5, 7, 2, 1.4, '#c8c4c8');
      p.p(0, 6, '#f0a0b0'); p.p(1, 6, '#e8e4e8');
      p.r(3, 5, 1, 1, '#1c1424'); p.p(3, 4, '#ffffff');
      p.r(4, 2, 2, 2, '#8e8a90'); p.p(5, 2, '#f0b0c0'); p.r(7, 3, 2, 1, '#6e6a72');
      p.r(5, 10, 1, 1, '#6e6a72'); p.r(12, 10, 1, 1, '#6e6a72'); p.r(7 + f, 10, 1, 1, '#5e5a62'); p.r(10 - f, 10, 1, 1, '#5e5a62');
      p.outline(OUT); return p.c;
    });
  }
  function horse(b = ['#8a5a32', '#6a4024', '#a87448'], m = '#efe0c0') {
    const fr = [0, 1].map(f => {
      const p = new Pix(36, 30);
      const bd = dk(b[1], 0.3), md = dk(m, 0.18);
      // tail
      p.poly([[29, 10], [33, 12 + f], [34, 22 + f], [31, 20]], md); p.poly([[29, 10], [32, 12 + f], [32, 20 + f]], m);
      // far legs
      [[12, 1], [26, 1]].forEach(([x]) => { p.r(x, 17, 3, 9, bd); p.r(x, 25, 3, 2, '#2a1a10'); });
      p.e(18, 14, 11, 6, b[0]); p.e(19, 16.5, 9, 3, b[1]); p.e(16, 11, 8, 2.2, b[2]);
      p.e(26, 13, 3, 3, b[2]); p.e(10, 14, 3, 3, b[1]);
      // near legs with feathering & hooves
      [[8, 0], [23, 0]].forEach(([x]) => { p.r(x, 17, 3, 9, b[0]); p.r(x, 17, 1, 9, b[2]); p.r(x, 23, 3, 2, m); p.r(x, 25, 3, 2, '#3a2a20'); });
      // harness
      p.r(12, 11, 2, 8, '#5a3020'); p.r(12, 12, 2, 1, P.gold[0]);
      // neck & head
      p.poly([[5, 4], [11, 2], [13, 13], [7, 13]], b[0]); p.poly([[6, 6], [9, 4], [10, 12], [7, 12]], b[2]);
      p.poly([[1, 7 + f], [6, 2], [9, 6], [5, 11 + f], [1, 10 + f]], b[0]);
      p.r(1, 9 + f, 4, 2, b[1]); p.p(2, 9 + f, '#2a1a10'); p.p(1, 11 + f, '#c8a888');
      p.r(5, 4, 2, 2, '#1c1424'); p.p(5, 4, '#ffffff');
      p.poly([[6, 2], [7, -1], [8.5, 2]], b[0]);
      p.ln(2, 7 + f, 7, 5, '#5a3020'); p.ln(7, 5, 9, 9, '#5a3020');   // bridle
      p.poly([[7, 2], [12, 1], [14, 11], [11, 10]], m); p.ln(9, 3, 12, 10, md);
      p.r(3, 4, 1, 4, '#f4ece0');
      p.outline(OUT); return p;
    });
    return { left: fr.map(p => p.c), right: fr.map(p => p.flipped()), w: 36, h: 30 };
  }
  function fox() {
    return [0, 1].map(f => {
      const p = new Pix(20, 13);
      const o = '#d8702a', od = '#a84e1a', ol = '#f0a058';
      p.e(16, 7, 3.5, 2.6 + f * 0.4, o); p.e(18, 6.5, 1.8, 1.8, '#f4ece0');                 // bushy tail, white tip
      p.e(10, 7.5, 5.2, 3, o); p.e(10, 9, 4, 1.6, od); p.e(9, 6.2, 3.5, 1.2, ol);           // body
      p.r(6 + f, 9, 1, 3, '#2a1a14'); p.r(8 - f, 9, 1, 3, '#2a1a14'); p.r(12 + f, 9, 1, 3, '#2a1a14'); p.r(14 - f, 9, 1, 3, '#2a1a14');
      p.e(4.5, 5.5, 2.8, 2.4, o); p.e(4, 7, 2.2, 1.2, '#f4ece0');                          // head, white cheeks
      p.poly([[0.5, 6], [3, 5], [3, 7]], o); p.p(0, 6, '#2a1a14');                         // snout
      p.poly([[3, 4], [3.5, 1], [5, 3.5]], o); p.poly([[5, 3.5], [6.5, 1], [7, 4]], od); p.p(4, 2, '#2a1a14');
      p.p(4, 5, '#1c1424'); p.p(3, 5, '#ffffff');
      p.outline(OUT); return p.c;
    });
  }
  function monster() {
    const p = new Pix(44, 44);
    const b = ['#3a1426', '#22080f', '#7a2440'];
    p.poly([[6, 14], [0, 2], [16, 10]], b[2]); p.poly([[38, 14], [44, 2], [28, 10]], b[2]);
    p.e(22, 28, 12, 12, b[0]); p.e(22, 15, 9, 8, b[0]);
    p.poly([[14, 9], [12, 0], [18, 7]], b[1]); p.poly([[30, 9], [32, 0], [26, 7]], b[1]);
    p.r(15, 13, 4, 2, '#ff4040'); p.r(25, 13, 4, 2, '#ff4040'); p.p(16, 13, '#ffe0a0'); p.p(26, 13, '#ffe0a0');
    p.r(16, 19, 12, 3, '#120006'); for (let i = 0; i < 5; i++) p.p(17 + i * 2, 19, '#f0e0e0');
    p.outline(OUT); return p.c;
  }

  // =================================================================== TILES
  const GROUND = {}; // name -> fn(p, x, y, rnd)
  function speck(p, rnd, n, cols, x0 = 0, y0 = 0, w = 16, h = 16) { for (let i = 0; i < n; i++) p.p(x0 + Math.floor(rnd() * w), y0 + Math.floor(rnd() * h), cols[Math.floor(rnd() * cols.length)]); }
  function tuft(p, x, y, c) { p.p(x, y, c); p.p(x + 2, y, c); p.p(x + 1, y - 1, c); }
  GROUND.grass = (p, rnd) => { p.r(0, 0, 16, 16, '#5f9e3f'); speck(p, rnd, 14, ['#4f8a34', '#6fae4a', '#578f38']); for (let i = 0; i < 5; i++) { const x = Math.floor(rnd() * 15), y = 2 + Math.floor(rnd() * 13); p.p(x, y, '#4a8230'); p.p(x, y - 1, rnd() < 0.5 ? '#7cbc52' : '#4f8a34'); } for (let i = 0; i < 2; i++) if (rnd() < 0.6) tuft(p, 1 + Math.floor(rnd() * 12), 3 + Math.floor(rnd() * 12), '#7cbc52'); };
  GROUND.leafy = (p, rnd) => { GROUND.grass(p, rnd); speck(p, rnd, 5, ['#e0902a', '#e8c040', '#c05030', '#a86a2a']); };
